out = {"tr": {}, "en": {}}
for ns, keys in M.items():
    for i, lang in enumerate(["tr", "en"]):
        out[lang].setdefault(ns, {})
        for k, v in keys.items():
            out[lang][ns][k] = v[i]
for lang in out:
    with open(f"messages/{lang}.json", "w", encoding="utf-8") as f:
        json.dump(out[lang], f, ensure_ascii=False, indent=2)
